<style>
  body { font-family: 'Inter', sans-serif; }
  .font-serif-custom { font-family: 'Newsreader', serif; }
  html { scroll-behavior: smooth; }
  .no-scrollbar::-webkit-scrollbar { display: none; }
  .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

  @keyframes float-subtle {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }
  .animate-float { animation: float-subtle 6s ease-in-out infinite; }
  .delay-200 { animation-delay: 200ms; }
  .delay-500 { animation-delay: 500ms; }

  [style*="--border-gradient"] { position: relative; }
  [style*="--border-gradient"]::before {
    content: "";
    position: absolute;
    inset: 0;
    padding: 1px;
    border-radius: var(--border-radius-before, inherit);
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    background: var(--border-gradient);
    pointer-events: none;
  }

  /* Typewriter cursor */
  .typed-cursor {
    display: inline-block;
    width: 3px;
    margin-left: 2px;
    background: #ec4899;
    animation: blink 0.9s step-start infinite;
  }
  @keyframes blink { 50% { opacity: 0; } }

  .nav-link.active {
    color: #fff;
    background: rgba(255,255,255,0.1);
  }

  .portfolio-tab-btn { color: #a1a1aa; }
  .portfolio-tab-btn.active {
    color: #fff;
    background: rgba(255,255,255,0.1);
  }

  .portfolio-card {
    position: relative;
    transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease, background-color 0.25s ease;
    cursor: pointer;
    outline: none;
  }
  .portfolio-card:hover,
  .portfolio-card:focus-visible,
  .portfolio-card.is-selected {
    transform: translateY(-6px) scale(1.015);
    border-color: rgba(216, 180, 254, 0.55);
    box-shadow: 0 18px 40px rgba(168, 85, 247, 0.18);
    background: rgba(255, 255, 255, 0.06);
  }
  .portfolio-card img {
    transition: transform 0.35s ease, filter 0.35s ease;
    transform-origin: center;
  }
  .portfolio-card:hover img,
  .portfolio-card:focus-visible img,
  .portfolio-card.is-selected img {
    transform: scale(1.06);
    filter: saturate(1.1);
  }
  .portfolio-card .card-action {
    transition: transform 0.2s ease, opacity 0.2s ease;
  }
  .portfolio-card:hover .card-action,
  .portfolio-card:focus-visible .card-action,
  .portfolio-card.is-selected .card-action {
    transform: translateX(0);
    opacity: 1;
  }

  #mobile-menu { transition: max-height 0.3s ease, opacity 0.3s ease; }

  .timeline-dot::before {
    content: "";
    position: absolute;
    left: -5px;
    top: 4px;
    width: 10px;
    height: 10px;
    border-radius: 9999px;
    background: linear-gradient(135deg, #a855f7, #9333ea);
    box-shadow: 0 0 12px rgba(168,85,247,0.6);
  }

  /* Scroll-reveal targets animated by Motion (initial state, JS animates to visible) */
  .reveal, .reveal-card, .reveal-item {
    opacity: 0;
    transform: translateY(28px);
    will-change: transform, opacity;
  }

  main { perspective: 1400px; }
  .tilt-card { transform-style: preserve-3d; will-change: transform; }

  /* Cursor-reactive spotlight glow */
  #cursor-glow {
    background: radial-gradient(600px circle at var(--x, 50%) var(--y, 50%), rgba(236,72,153,0.28), transparent 70%);
  }

  /* Tint overlay: pushes the UnicornStudio background toward a purple/pink palette */
  #theme-tint {
    background: linear-gradient(135deg, rgba(168,85,247,0.45), rgba(217,70,239,0.3) 45%, rgba(236,72,153,0.45));
    mix-blend-mode: color;
  }

  /* Aurora animated background — jaminan tetap bergerak & ungu-pink walau embed pihak ketiga gagal dimuat */
  #aurora-bg { position: fixed; inset: 0; width: 100%; height: 100%; z-index: -11; overflow: hidden; pointer-events: none; background: #0b0512; }
  #aurora-bg .blob { position: absolute; border-radius: 9999px; filter: blur(110px); opacity: 0.55; }
  #aurora-bg .blob-1 { width: 700px; height: 700px; top: -15%; left: -10%; background: radial-gradient(circle, #a855f7, transparent 70%); animation: aurora-drift-1 16s ease-in-out infinite; }
  #aurora-bg .blob-2 { width: 640px; height: 640px; top: 20%; right: -15%; background: radial-gradient(circle, #ec4899, transparent 70%); animation: aurora-drift-2 20s ease-in-out infinite; }
  #aurora-bg .blob-3 { width: 560px; height: 560px; bottom: -20%; left: 25%; background: radial-gradient(circle, #d946ef, transparent 70%); animation: aurora-drift-3 24s ease-in-out infinite; }

  @keyframes aurora-drift-1 {
    0%, 100% { transform: translate(0, 0) scale(1); }
    33% { transform: translate(12%, 8%) scale(1.15); }
    66% { transform: translate(-6%, 14%) scale(0.9); }
  }
  @keyframes aurora-drift-2 {
    0%, 100% { transform: translate(0, 0) scale(1); }
    33% { transform: translate(-14%, 10%) scale(0.9); }
    66% { transform: translate(-4%, -12%) scale(1.2); }
  }
  @keyframes aurora-drift-3 {
    0%, 100% { transform: translate(0, 0) scale(1); }
    33% { transform: translate(10%, -14%) scale(1.1); }
    66% { transform: translate(-10%, -4%) scale(0.95); }
  }

  @media (prefers-reduced-motion: reduce) {
    #aurora-bg .blob { animation: none; }
  }

  /* Tech stack: marquee logo berjalan berkelanjutan */
  .marquee-stack {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }
  .marquee-row {
    overflow: hidden;
    position: relative;
    -webkit-mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
    mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
  }
  .marquee-row-track {
    display: flex;
    width: max-content;
    animation: marquee-scroll 26s linear infinite;
  }
  .marquee-row.reverse .marquee-row-track {
    animation-direction: reverse;
    animation-duration: 30s;
  }
  .marquee-row:hover .marquee-row-track { animation-play-state: paused; }
  .marquee-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    padding-right: 0.85rem;
    flex-shrink: 0;
  }
  .tech-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.8rem;
    white-space: nowrap;
    padding: 0.9rem 1.5rem;
    border-radius: 9999px;
