    </section>

    <div id="portfolio-modal" class="fixed inset-0 z-[110] hidden items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div class="relative w-full max-w-5xl rounded-[2rem] border border-white/10 bg-[#120d1a]/95 p-3 shadow-2xl shadow-fuchsia-950/30">
        <button id="close-portfolio-modal" type="button" class="absolute right-4 top-4 z-10 flex h-10 w-10 items-center justify-center rounded-full bg-black/40 text-xl text-white border border-white/10 hover:bg-white/10 transition-colors">×</button>
        <img id="portfolio-modal-image" src="" alt="Preview certificate" class="max-h-[80vh] w-full rounded-[1.4rem] object-contain bg-white/5">
